<script lang="ts">
  import DashboardContent from '$lib/components/DashboardContent.svelte';
  import { CalendarDays, CheckCircle2, ClipboardCheck, Megaphone, Users, WalletCards, ArrowRight, Clock3, ListTodo } from 'lucide-svelte';
  const { data } = $props();
  const stats = $derived(data.stats);
  const teacher = $derived(data.teacher);
  const occurrences = $derived(data.occurrences ?? []);
  const announcements = $derived(data.announcements ?? []);
  const calendarEvents = $derived(data.calendarEvents ?? []);
  const tasks = $derived(data.tasks ?? []);
  const today = new Date().toISOString().slice(0, 10);
  const todaySessions = $derived(occurrences.filter((o: any) => o.occurs_on === today));
  const dueSessions = $derived(todaySessions.filter((o: any) => o.attendance?.approval_status !== 'approved'));
  const nextSession = $derived(todaySessions.find((o: any) => o.start_time >= new Date().toTimeString().slice(0, 8)) ?? todaySessions[0] ?? null);
  const remedialRole = $derived(teacher?.remedial_role ?? 'none');
  const isCommittee = $derived(['chairman', 'treasurer', 'member'].includes(remedialRole));
  const teacherTypeLabel = $derived(data.teacherType === 'remedial' ? 'Remedial teacher' : data.teacherType === 'classroom' ? 'Classroom teacher' : data.teacherType === 'both' ? 'Remedial & classroom teacher' : 'Teacher');
  const time = (value: string | null | undefined) => value?.slice(0, 5) ?? '—';
  const calendarTime = (value: string) => new Date(value).toLocaleString([], { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
  const dueLabel = (value: string) => new Date(value).toLocaleString([], { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
</script>
<svelte:head><title>Teacher workspace · eShule</title><meta name="description" content="Your teaching day, sessions, attendance and responsibilities in eShule." /></svelte:head>
<DashboardContent title="{teacherTypeLabel} workspace" subtitle="Your day is organized around the work assigned to you.">
  <div class="space-y-7">
    <section class="ui-card overflow-hidden border-primary/15 bg-primary/5 p-6 sm:p-8">
      <div class="flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between"><div><p class="text-xs font-bold uppercase tracking-[0.16em] text-primary">Today</p><h1 class="mt-2 text-3xl font-semibold tracking-tight text-ink-900">Good morning{teacher?.first_name ? `, ${teacher.first_name}` : ''}.</h1><p class="mt-3 max-w-xl text-sm leading-6 text-ink-500">Teach first. Record attendance immediately after each session so delivery evidence stays current.</p></div>{#if dueSessions.length > 0}<a href="#attendance" class="ui-action ui-action-primary"><ClipboardCheck class="h-4 w-4" /> Clear {dueSessions.length} attendance task{dueSessions.length === 1 ? '' : 's'}</a>{:else}<span class="ui-status ui-status-success"><CheckCircle2 class="h-4 w-4" /> All attendance cleared</span>{/if}</div>
      <div class="mt-6 grid gap-3 sm:grid-cols-3"><div class="ui-card p-4"><p class="text-xs text-ink-400">Today's sessions</p><p class="mt-1 text-2xl font-bold text-ink-900">{todaySessions.length}</p></div><div class="ui-card p-4"><p class="text-xs text-ink-400">Pending review</p><p class="mt-1 text-2xl font-bold text-ink-900">{stats?.pending ?? 0}</p></div><div class="ui-card p-4"><p class="text-xs text-ink-400">Open tasks</p><p class="mt-1 text-2xl font-bold text-ink-900">{tasks.length}</p></div></div>
    </section>

    {#if nextSession}<section class="rounded-2xl border border-primary/20 bg-primary/5 p-5 sm:p-6"><div class="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><p class="text-xs font-bold uppercase tracking-[0.14em] text-primary">Next up</p><h2 class="mt-1 text-xl font-semibold text-ink-900">{nextSession.subject || 'Session'} · {nextSession.class ?? 'Class'}</h2><p class="mt-1 text-sm text-ink-500">{time(nextSession.start_time)}–{time(nextSession.end_time)} · {nextSession.room ?? 'Room not set'}</p></div><a href="/teacher/timetable" class="ui-action ui-action-secondary">Open timetable <ArrowRight class="h-4 w-4" /></a></div></section>{/if}

    <div class="grid gap-6 lg:grid-cols-[minmax(0,1.4fr)_minmax(280px,0.8fr)]">
      {#if data.canRemedial}<section id="attendance" class="ui-card overflow-hidden"><div class="border-b border-border/60 px-5 py-4 sm:px-6"><h2 class="text-lg font-semibold text-ink-900">Attendance to clear</h2><p class="mt-1 text-sm text-ink-400">Record only Attended or Absent. Approved attendance becomes payroll evidence.</p></div>{#if todaySessions.length === 0}<div class="p-10 text-center"><CalendarDays class="mx-auto h-8 w-8 text-ink-300" /><p class="mt-3 text-sm font-semibold text-ink-700">No remedial sessions today</p><p class="mt-1 text-xs text-ink-400">Your next assigned session will appear here when scheduled.</p></div>{:else}<div class="divide-y divide-border/60">{#each todaySessions as occurrence}<div class="flex flex-col gap-4 px-5 py-4 sm:flex-row sm:items-center sm:justify-between sm:px-6"><div class="min-w-0"><div class="flex items-center gap-2"><Clock3 class="h-4 w-4 shrink-0 text-primary" /><p class="truncate text-sm font-semibold text-ink-900">{occurrence.subject || 'Subject'} · {occurrence.class ?? 'Class'}</p></div><p class="mt-1 text-xs text-ink-500">{time(occurrence.start_time)}–{time(occurrence.end_time)} · {occurrence.room ?? 'Room not set'}</p>{#if occurrence.attendance}<span class="ui-status mt-2 {occurrence.attendance.approval_status === 'approved' ? 'ui-status-success' : occurrence.attendance.status === 'absent' ? 'ui-status-danger' : 'ui-status-info'}">{occurrence.attendance.status} · {occurrence.attendance.approval_status}</span>{/if}</div>{#if occurrence.attendance?.approval_status !== 'approved'}<div class="grid w-full grid-cols-2 gap-2 sm:w-auto"><form method="POST" action="?/mark"><input type="hidden" name="occurrence_id" value={occurrence.id} /><input type="hidden" name="status" value="attended" /><button class="ui-action ui-action-primary min-h-11 w-full justify-center">Attended</button></form><form method="POST" action="?/mark"><input type="hidden" name="occurrence_id" value={occurrence.id} /><input type="hidden" name="status" value="absent" /><button class="ui-action ui-action-secondary min-h-11 w-full justify-center">Absent</button></form></div>{:else}<span class="ui-status ui-status-success"><CheckCircle2 class="h-3.5 w-3.5" /> Approved</span>{/if}</div>{/each}</div>{/if}</section>{/if}

      <section class="ui-card overflow-hidden"><div class="border-b border-border/60 px-5 py-4"><div class="flex items-center gap-2"><ListTodo class="h-5 w-5 text-primary" /><div><h2 class="text-lg font-semibold text-ink-900">My work queue</h2><p class="mt-1 text-sm text-ink-400">Tasks assigned directly to you.</p></div></div></div>{#if tasks.length === 0}<div class="p-8 text-center"><CheckCircle2 class="mx-auto h-8 w-8 text-ink-300" /><p class="mt-3 text-sm font-semibold text-ink-700">Nothing outstanding</p></div>{:else}<div class="divide-y divide-border/60">{#each tasks as task}<article class="px-5 py-4"><div class="flex items-start justify-between gap-3"><h3 class="text-sm font-semibold text-ink-900">{task.title}</h3><span class="ui-status {task.priority === 'urgent' ? 'ui-status-danger' : task.priority === 'high' ? 'ui-status-warning' : 'ui-status-info'}">{task.priority}</span></div>{#if task.description}<p class="mt-1 text-xs leading-5 text-ink-500">{task.description}</p>{/if}<p class="mt-2 text-xs text-ink-400">Due {dueLabel(task.due_at)}</p></article>{/each}</div>{/if}</section>
    </div>

    <section class="ui-card overflow-hidden"><div class="flex items-center justify-between border-b border-border/60 px-5 py-4 sm:px-6"><div class="flex items-center gap-2"><CalendarDays class="h-5 w-5 text-primary" /><div><h2 class="text-lg font-semibold text-ink-900">School calendar</h2><p class="mt-1 text-sm text-ink-400">Dates that affect your teaching work.</p></div></div><a href="/admin/calendar" class="text-xs font-semibold text-primary hover:underline">Open calendar</a></div>{#if calendarEvents.length === 0}<div class="p-8 text-sm text-ink-400">No upcoming teacher-facing events.</div>{:else}<div class="grid gap-3 p-4 sm:grid-cols-2 lg:grid-cols-4">{#each calendarEvents.slice(0, 4) as event}<article class="rounded-xl border border-border/60 p-4"><span class="ui-status ui-status-info">{event.event_type}</span><h3 class="mt-3 text-sm font-semibold text-ink-900">{event.title}</h3><p class="mt-1 text-xs text-ink-500">{calendarTime(event.starts_at)}</p>{#if event.location}<p class="mt-2 text-xs text-ink-400">{event.location}</p>{/if}</article>{/each}</div>{/if}</section>

    <div class="grid gap-4 sm:grid-cols-2">{#if data.canSis}<a href="/teacher/classes" class="ui-card group p-5 transition hover:-translate-y-0.5"><div class="flex items-center justify-between"><Users class="h-5 w-5 text-primary" /><ArrowRight class="h-4 w-4 text-ink-300 group-hover:text-primary" /></div><h2 class="mt-4 text-sm font-semibold text-ink-900">My classes</h2><p class="mt-1 text-xs leading-5 text-ink-500">Open the rosters and classroom responsibilities assigned to you.</p></a>{/if}{#if isCommittee}<a href="/teacher/committee" class="rounded-2xl border border-amber-200 bg-amber-50/60 p-5 transition hover:-translate-y-0.5"><div class="flex items-center justify-between"><WalletCards class="h-5 w-5 text-amber-700" /><ArrowRight class="h-4 w-4 text-amber-500" /></div><h2 class="mt-4 text-sm font-semibold text-ink-900">Committee responsibilities</h2><p class="mt-1 text-xs leading-5 text-ink-600">Your {remedialRole} role controls the governance actions available to you.</p></a>{/if}</div>
    {#if announcements.length > 0}<section><div class="mb-4 flex items-center gap-2"><Megaphone class="h-5 w-5 text-primary" /><div><h2 class="text-lg font-semibold text-ink-900">Announcements</h2><p class="mt-1 text-sm text-ink-400">Important updates from your school.</p></div></div><div class="grid gap-4 sm:grid-cols-2">{#each announcements.slice(0, 4) as announcement}<article class="ui-card p-5"><div class="flex items-start justify-between gap-3"><h3 class="text-sm font-semibold text-ink-900">{announcement.title}</h3>{#if announcement.priority === 'urgent'}<span class="ui-status ui-status-danger">Urgent</span>{/if}</div><p class="mt-2 line-clamp-3 whitespace-pre-wrap text-sm leading-5 text-ink-500">{announcement.body}</p></article>{/each}</div></section>{/if}
  </div>
</DashboardContent>